 static void command(Context c,String action)throws Exception{CallService a=active;if(a==null)throw new Exception("当前没有通话");if(action.equals("hangup"))a.end("用户挂断");else if(action.equals("mute")){a.muted=!a.muted;if(a.muted&&!a.phase.equals("thinking")&&!a.phase.equals("synthesizing")&&!a.phase.equals("speaking")){a.token=a.epoch.next();a.stopRecognizer();a.state("muted");}else if(!a.phase.equals("thinking")&&!a.phase.equals("synthesizing")&&!a.phase.equals("speaking"))a.listen();}else if(action.equals("speaker")){a.speaker=!a.speaker;try{a.route();}catch(Exception e){a.end("系统音频路由不可用");}}else if(action.equals("interrupt")){a.cancelTurn();a.listen();}else if(action.equals("retry")){a.cancelTurn();a.listen();}}
