   focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_VOICE_COMMUNICATION).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setOnAudioFocusChangeListener(change->{if(change<0&&!closing)end("音频被系统电话或其他应用占用");},main).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED)throw new Exception("系统未授予通话音频焦点");audio.setMode(AudioManager.MODE_IN_COMMUNICATION);route();wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Eidolon:VoiceCall");wake.acquire(CallLimits.MAX_MILLIS);main.postDelayed(()->end("达到单次30分钟通话上限"),CallLimits.MAX_MILLIS);listen();
