 void notification(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"应用内语音通话",NotificationManager.IMPORTANCE_LOW));if(nm.getNotificationChannel(CHANNEL).getImportance()==NotificationManager.IMPORTANCE_NONE)throw new IllegalStateException("系统关闭了通话通知，请先在通知设置中允许");Intent open=new Intent(this,WebActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent content=PendingIntent.getActivity(this,9760,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getService(this,9761,new Intent(this,CallService.class).setAction("hangup").putExtra("callId",row.optString("id")),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.sym_call_incoming).setContentTitle("Eidolon 随行 · 语音通话").setContentText("应用内AI通话，点击返回；可随时挂断").setContentIntent(content).setOngoing(true).setCategory(Notification.CATEGORY_CALL).addAction(new Notification.Action.Builder(null,"挂断",stop).build()).build();if(Build.VERSION.SDK_INT>=30)startForeground(NOTICE,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE|android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else if(Build.VERSION.SDK_INT>=29)startForeground(NOTICE,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(NOTICE,n);}
 void state(String value){phase=value;try{row.put("state",value);CallStore.put(store,row);}catch(Exception e){end("通话状态无法保存");}}
