  recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){if(valid(own)&&phase.equals("connecting")){if(connectedMono==0){connectedMono=SystemClock.elapsedRealtime();try{row.put("connectedAt",System.currentTimeMillis());}catch(Exception ignored){}}state("listening");}}public void onBeginningOfSpeech(){if(recognizing(own))utteranceAt=System.currentTimeMillis();}public void onRmsChanged(float r){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){if(recognizing(own)){speechEnd=SystemClock.elapsedRealtime();if(utteranceAt==0)utteranceAt=System.currentTimeMillis();state("recognizing");}}public void onError(int code){if(recognizing(own)){stopRecognizer();error="识别未完成（系统代码 "+code+"），可重试聆听；不会自动重发模型请求";state("failed");}}public void onResults(Bundle b){if(!recognizing(own))return;ArrayList<String> texts=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);stopRecognizer();if(texts==null||texts.isEmpty()||texts.get(0).trim().isEmpty()){error="没有识别到有效讲话，可重试聆听";state("failed");return;}recognizedAt=SystemClock.elapsedRealtime();user=texts.get(0).trim();float[] confidence=b.getFloatArray(SpeechRecognizer.CONFIDENCE_SCORES);if(confidence!=null&&confidence.length>0&&confidence[0]>=0&&confidence[0]<.45f){error="识别置信度较低，本轮未提交，请重新聆听";state("failed");return;}generate(own,user);}public void onPartialResults(Bundle b){if(recognizing(own)){ArrayList<String> t=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(t!=null&&!t.isEmpty())user=t.get(0);}}public void onEvent(int type,Bundle b){}});
